const mongoose = require('mongoose');

/**
 * A resume generated by the AI "Resume Maker" for a logged in user.
 * `content` holds the structured resume so the frontend can render / print it.
 */

const resumeContentSchema = new mongoose.Schema({
    fullName: { type: String, default: '' },
    headline: { type: String, default: '' },
    contact: {
        email: { type: String, default: '' },
        phone: { type: String, default: '' },
        location: { type: String, default: '' },
        links: [{ type: String }]
    },
    summary: { type: String, default: '' },
    skills: [{
        category: { type: String },
        items: [{ type: String }],
        _id: false
    }],
    experience: [{
        role: String,
        company: String,
        location: String,
        duration: String,
        bullets: [String],
        _id: false
    }],
    projects: [{
        name: String,
        techStack: String,
        link: String,
        bullets: [String],
        _id: false
    }],
    education: [{
        degree: String,
        institution: String,
        year: String,
        details: String,
        _id: false
    }],
    certifications: [String],
    achievements: [String]
}, { _id: false });

const resumeSchema = new mongoose.Schema({
    user: {
        type: mongoose.Schema.Types.ObjectId,
        ref: 'users',
        required: true,
        index: true
    },
    title: {
        type: String,
        required: [true, 'Resume title is required']
    },
    targetRole: { type: String, default: '' },
    jobDescription: { type: String, default: '' },
    selfDescription: {
        type: String,
        required: [true, 'Self description is required']
    },
    atsScore: { type: Number, min: 0, max: 100 },
    improvementTips: [{ type: String }],
    content: resumeContentSchema
}, { timestamps: true });

module.exports = mongoose.model('Resume', resumeSchema);
